versions.variantCss:
.wemd-magazine-cover[data-variant="bytedance-cover-vibrant"] {
  background: var(--wemd-bg-card);
  border-top: 6px solid var(--wemd-primary);
  border-radius: var(--wemd-border-radius);
  padding: 48px 32px 40px 32px;
  margin: 0 0 24px 0;
  text-align: center;
  box-shadow: var(--wemd-shadow);
}
.wemd-magazine-cover[data-variant="bytedance-cover-vibrant"] .wemd-mc-subtitle {
  color: var(--wemd-primary);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  margin: 0 0 16px 0;
}
.wemd-magazine-cover[data-variant="bytedance-cover-vibrant"] .wemd-mc-title {
  color: var(--wemd-text-strong);
  font-size: 36px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -1px;
  margin: 0 0 20px 0;
}
.wemd-magazine-cover[data-variant="bytedance-cover-vibrant"] .wemd-mc-divider {
  width: 48px;
  height: 3px;
  background: linear-gradient(90deg, var(--wemd-primary), var(--wemd-secondary));
  border-radius: 2px;
  margin: 0 auto 20px auto;
}
.wemd-magazine-cover[data-variant="bytedance-cover-vibrant"] .wemd-mc-desc {
  color: var(--wemd-text-soft);
  font-size: 14px;
  line-height: 1.7;
  margin: 0;
}
